package com.example.inventoryservice.dto.response;
import java.math.BigDecimal;
import java.time.LocalDateTime;
public class InventoryResponse { private Long inventoryId; private Long partnerId; private String partnerName; private String itemType; private String name; private BigDecimal price; private Integer availability; private String status; private String details; private LocalDateTime createdAt; public Long getInventoryId(){return inventoryId;} public void setInventoryId(Long v){this.inventoryId=v;} public Long getPartnerId(){return partnerId;} public void setPartnerId(Long v){this.partnerId=v;} public String getPartnerName(){return partnerName;} public void setPartnerName(String v){this.partnerName=v;} public String getItemType(){return itemType;} public void setItemType(String v){this.itemType=v;} public String getName(){return name;} public void setName(String v){this.name=v;} public BigDecimal getPrice(){return price;} public void setPrice(BigDecimal v){this.price=v;} public Integer getAvailability(){return availability;} public void setAvailability(Integer v){this.availability=v;} public String getStatus(){return status;} public void setStatus(String v){this.status=v;} public String getDetails(){return details;} public void setDetails(String v){this.details=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){this.createdAt=v;} }